"""A clump of wild grass: tapering blades fanning out from one root, olive green with dry yellow tips (generated by
npm run new). Variants: a short tuft, a taller tuft with seed-head stalks, a dry straw-coloured half-dead tuft."""
import math
import random

from propsmith import prop
from propsmith.materials import material
from propsmith.shapes import blob, cylinder

# The tuft stays under 0.45 m high and well inside 0.6 m across.
SHORT_H = 0.25  # metres, blade length of the short tuft
TALL_H = 0.36  # metres, blade length of the tall tuft
STALK_H = 0.43  # metres, seed-head stalks of the tall tuft
ROOT_R = 0.045  # metres, radius of the root crown
BLADE_R = 0.011  # metres, half-width of a blade at its base
TIP_SPLIT = 0.62  # fraction of a blade that is green before the dry tip
MAX_TILT = 58  # degrees from vertical for the outermost blades

OLIVE = (0.1, 0.13, 0.035)  # linear RGB
OLIVE_DARK = (0.06, 0.08, 0.025)
TIP = (0.33, 0.26, 0.08)  # dry yellow
STRAW = (0.44, 0.34, 0.15)
DEAD = (0.28, 0.21, 0.1)
ROOT = (0.08, 0.06, 0.03)
SEED = (0.3, 0.22, 0.09)


def _dir(tilt, yaw):
    """Unit vector of local +z after rot=(tilt, 0, yaw) degrees (XYZ Euler)."""
    t, y = math.radians(tilt), math.radians(yaw)
    return (math.sin(t) * math.sin(y), -math.sin(t) * math.cos(y), math.cos(t))


def _blade(name, length, tilt, yaw, low, tip, r=BLADE_R, split=TIP_SPLIT, bend=14):
    """One tapering blade: a lower segment in `low`, a bent upper segment in `tip`."""
    base = (0, 0, r * math.sin(math.radians(tilt)) + 0.001)
    l1 = length * split
    r_mid = r * 0.6
    cylinder(f"{name}_a", r, l1, base, low, r_top=r_mid, segments=4, rot=(tilt, 0, yaw), bevel=0)
    d = _dir(tilt, yaw)
    mid = (base[0] + d[0] * l1, base[1] + d[1] * l1, base[2] + d[2] * l1)
    t2 = min(tilt + bend, 100)
    cylinder(f"{name}_b", r_mid, length - l1, mid, tip, r_top=0.0008, segments=4, rot=(t2, 0, yaw), bevel=0)


def _root(mat, seed):
    blob("grass_root", ROOT_R, (0, 0, ROOT_R * 0.35), mat, squash=(1, 1, 0.4), subdiv=1, seed=seed, jitter=0.15)


def _tuft(rnd, n, length, mats, tips, dead=None, dead_share=0.0):
    for i in range(n):
        yaw = 360 * i / n + rnd.uniform(-18, 18)
        tilt = rnd.uniform(6, MAX_TILT) * (0.5 + 0.5 * (i % 3) / 2)
        ln = length * rnd.uniform(0.6, 1.0) * (1 - 0.25 * tilt / MAX_TILT)
        low = rnd.choice(mats)
        tip = rnd.choice(tips)
        if dead is not None and rnd.random() < dead_share:
            low, tip = dead, dead
            tilt = min(tilt + 25, 85)
        _blade(f"grass_blade_{i}", ln, tilt, yaw, low, tip, r=BLADE_R * rnd.uniform(0.8, 1.2),
               bend=rnd.uniform(8, 22))


def _green():
    olive = material("grass_olive", OLIVE, rough=0.85, vary=0.3, scale=30, crevice=0.6)
    dark = material("grass_olive_dark", OLIVE_DARK, rough=0.85, vary=0.3, scale=30, crevice=0.6)
    tip = material("grass_tip", TIP, rough=0.9, vary=0.25, scale=30, crevice=0.4)
    return olive, dark, tip


@prop
def grass_tuft():
    rnd = random.Random(3)
    olive, dark, tip = _green()
    _root(material("grass_root", ROOT, vary=0.2, scale=20), 5)
    _tuft(rnd, 38, SHORT_H, [olive, olive, dark], [tip, tip, olive])


@prop
def grass_tuft_tall():
    rnd = random.Random(8)
    olive, dark, tip = _green()
    _root(material("grass_root", ROOT, vary=0.2, scale=20), 9)
    _tuft(rnd, 42, TALL_H, [olive, olive, dark], [tip, tip, olive])
    seed = material("grass_seed", SEED, rough=0.9, vary=0.3, scale=40, crevice=0.5)
    for i in range(4):
        yaw = 90 * i + rnd.uniform(-30, 30)
        tilt = rnd.uniform(4, 16)
        ln = STALK_H * rnd.uniform(0.85, 0.97)
        base = (0, 0, 0.002)
        cylinder(f"grass_stalk_{i}", 0.003, ln, base, tip, r_top=0.002, segments=4, rot=(tilt, 0, yaw), bevel=0)
        d = _dir(tilt, yaw)
        head_l = 0.035
        top = (d[0] * (ln - head_l), d[1] * (ln - head_l), 0.002 + d[2] * (ln - head_l))
        cylinder(f"grass_head_{i}", 0.009, head_l, top, seed, r_top=0.003, segments=6, rot=(tilt, 0, yaw), bevel=0)


@prop
def grass_tuft_dry():
    rnd = random.Random(21)
    straw = material("grass_straw", STRAW, rough=0.95, vary=0.3, scale=30, crevice=0.5)
    dead = material("grass_dead", DEAD, rough=0.95, vary=0.25, scale=30, crevice=0.5)
    olive = material("grass_olive_dry", OLIVE, rough=0.85, vary=0.3, scale=30, crevice=0.6)
    _root(material("grass_root", ROOT, vary=0.2, scale=20), 13)
    _tuft(rnd, 36, SHORT_H * 0.9, [straw, straw, olive], [straw, straw, dead], dead=dead, dead_share=0.35)
